// === Tab: mySketch ===
/*
Scribble brush

Recursively spawns new particles to create a sort of scribble-like effect.

Controls:
	- Drag the mouse to spawn particles.

Author:
  	Jason Labbe

Site:
  	jasonlabbe3d.com
*/

var allParticles = [];
var baseHue = 100;
var maxLevel = 4;


// Moves to a random direction and comes to a stop.
// Spawns other particles within its lifetime.
function Particle(x, y, level) {
  this.level = level
  this.life = 0;

  this.pos = new p5.Vector(x, y);
  this.vel = p5.Vector.random2D();
  this.vel.mult(map(this.level, 0, maxLevel, 5, 0.5));

  this.move = function() {
    this.life++;

    this.vel.mult(0.95);
    this.pos.add(this.vel);

    if (this.life % 20 == 0) {
      if (this.level > 0) {
        this.level -= 1;
        var newParticle = new Particle(this.pos.x, this.pos.y, this.level-1);
        allParticles.push(newParticle);
      }
    }
  }
}


function setup() {
  createCanvas(windowWidth, windowHeight); 

  colorMode(HSB, 360);

  noFill();
} 


function draw() {
  // Background color should always be complimentary to the current stroke.
  bgHue = baseHue+150;
  if (bgHue > 360) {
    bgHue = bgHue-360;
  }

  background(bgHue, 255, 255);

  stroke(this.baseHue, 360, 360);

  beginShape();

  for (var i = allParticles.length-1; i > -1; i--) {
    allParticles[i].move();

    curveVertex(allParticles[i].pos.x, allParticles[i].pos.y);

    strokeWeight(min(i*0.01, 10));
    point(allParticles[i].pos.x, allParticles[i].pos.y);

    if (allParticles[i].vel.mag() < 0.1) {
      allParticles.splice(i, 1);
    }
  }

  strokeWeight(min(allParticles.length*0.001, 0.5));
  endShape();
}


function mouseDragged() {
  allParticles.push(new Particle((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), maxLevel));

  baseHue += 0.1;
  if (baseHue > 360) {
    baseHue = 0;
  }
}

